package main

import (
	"context"
	"errors"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/immuta/operations/services/beammeup/internal/config"
	"github.com/immuta/operations/services/beammeup/internal/slack"
	"github.com/immuta/operations/services/beammeup/internal/state"
	"github.com/immuta/operations/services/beammeup/internal/teleport"
	"github.com/labstack/echo/v4"
	"github.com/labstack/echo/v4/middleware"
	slackapi "github.com/slack-go/slack"
)

func main() {
	logger := slog.New(slog.NewJSONHandler(os.Stdout, nil))
	slog.SetDefault(logger)

	cfg, err := config.Load()
	if err != nil {
		slog.Error("configuration error", "error", err)
		os.Exit(1)
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	tpClient, err := teleport.NewClient(ctx, cfg)
	if err != nil {
		slog.Error("teleport client error", "error", err)
		os.Exit(1)
	}
	defer tpClient.Close()

	store := state.New()
	slackClient := slackapi.New(cfg.SlackBotToken)
	h := slack.NewHandler(cfg, slackClient, tpClient, store)

	go func() {
		if err := teleport.Watch(ctx, tpClient, func(req teleport.AccessRequest) {
			if err := h.PostAccessRequest(req); err != nil {
				slog.Error("failed to post access request", "error", err, "id", req.ID)
			}
		}); err != nil {
			slog.Error("teleport watcher exited", "error", err)
			stop()
		}
	}()

	e := echo.New()
	e.HideBanner = true
	e.Use(middleware.Recover())
	h.Register(e)
	e.GET("/livez", func(c echo.Context) error { return c.NoContent(http.StatusOK) })
	e.GET("/readyz", func(c echo.Context) error { return c.NoContent(http.StatusOK) })

	go func() {
		slog.Info("listening", "port", cfg.Port)
		if err := e.Start(":" + cfg.Port); err != nil && !errors.Is(err, http.ErrServerClosed) {
			slog.Error("server error", "error", err)
			os.Exit(1)
		}
	}()

	quit := make(chan os.Signal, 1)
	signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)
	<-quit

	shutCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := e.Shutdown(shutCtx); err != nil {
		slog.Error("shutdown error", "error", err)
	}
}

