package config

import (
	"errors"
	"os"
)

type Config struct {
	TeleportProxyAddr    string
	TeleportIdentityFile string
	SlackBotToken        string
	SlackSigningSecret   string
	SlackChannel         string
	Port                 string
}

func Load() (*Config, error) {
	cfg := &Config{
		TeleportProxyAddr:    os.Getenv("TELEPORT_PROXY_ADDR"),
		TeleportIdentityFile: os.Getenv("TELEPORT_IDENTITY_FILE"),
		SlackBotToken:        os.Getenv("SLACK_BOT_TOKEN"),
		SlackSigningSecret:   os.Getenv("SLACK_SIGNING_SECRET"),
		SlackChannel:         os.Getenv("SLACK_CHANNEL"),
		Port:                 os.Getenv("PORT"),
	}

	if cfg.Port == "" {
		cfg.Port = "8080"
	}

	var errs []error
	if cfg.TeleportProxyAddr == "" {
		errs = append(errs, errors.New("TELEPORT_PROXY_ADDR is required"))
	}
	if cfg.TeleportIdentityFile == "" {
		errs = append(errs, errors.New("TELEPORT_IDENTITY_FILE is required"))
	}
	if cfg.SlackBotToken == "" {
		errs = append(errs, errors.New("SLACK_BOT_TOKEN is required"))
	}
	if cfg.SlackSigningSecret == "" {
		errs = append(errs, errors.New("SLACK_SIGNING_SECRET required"))
	}
	if cfg.SlackChannel == "" {
		errs = append(errs, errors.New("SLACK_CHANNEL is required"))
	}

	return cfg, errors.Join(errs...)
}

