type Entry struct {
	TeleportRequestID string
	SlackChannel      string
	SlackMessageTS    string
	Requester         string
	Roles             []string
	Reason            string
}

type Store struct {
	mu  sync.RWMutex
	idx map[string]*Entry
}

func New() *Store {
	return &Store{idx: make(map[string]*Entry)}
}

func (s *Store) Set(e *Entry) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.idx[e.TeleportRequestID] = e
}

func (s *Store) Get(id string) (*Entry, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	e, ok := s.idx[id]
	return e, ok
}

func (s *Store) Delete(id string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	delete(s.idx, id)
}

