package teleport

import (
	"context"
	"fmt"

	"github.com/gravitational/teleport/api/client"
	"github.com/gravitational/teleport/api/types"
	"github.com/immuta/operations/services/beammeup/internal/config"
)

// AccessRequest is a simplified view of a Teleport access request.
type AccessRequest struct {
	ID        string
	Requester string
	Roles     []string
	Reason    string
}

type Client struct {
	inner *client.Client
}

func NewClient(ctx context.Context, cfg *config.Config) (*Client, error) {
	clt, err := client.New(ctx, client.Config{
		Addrs:       []string{cfg.TeleportProxyAddr},
		Credentials: []client.Credentials{client.LoadIdentityFile(cfg.TeleportIdentityFile)},
	})
	if err != nil {
		return nil, fmt.Errorf("connecting to teleport: %w", err)
	}
	return &Client{inner: clt}, nil
}

func (c *Client) Close() error {
	return c.inner.Close()
}

func (c *Client) Approve(ctx context.Context, requestID, approver string) error {
	return c.inner.SetAccessRequestState(ctx, types.AccessRequestUpdate{
		RequestID: requestID,
		State:     types.RequestState_APPROVED,
		Delegator: approver,
	})
}

func (c *Client) Deny(ctx context.Context, requestID, reason, delegator string) error {
	return c.inner.SetAccessRequestState(ctx, types.AccessRequestUpdate{
		RequestID: requestID,
		State:     types.RequestState_DENIED,
		Reason:    reason,
		Delegator: delegator,
	})
}

