package teleport

import (
	"context"
	"fmt"
	"log/slog"
	"time"

	"github.com/gravitational/teleport/api/types"
)

// Watch streams pending access requests and calls onRequest for each one.
// Reconnects automatically on disconnect until ctx is cancelled.
func Watch(ctx context.Context, c *Client, onRequest func(AccessRequest)) error {
	for {
		if ctx.Err() != nil {
			return nil
		}
		if err := watch(ctx, c, onRequest); err != nil {
			if ctx.Err() != nil {
				return nil
			}
			slog.Warn("watcher disconnected, reconnecting in 5s", "error", err)
			select {
			case <-ctx.Done():
				return nil
			case <-time.After(5 * time.Second):
			}
		}
	}
}

func watch(ctx context.Context, c *Client, onRequest func(AccessRequest)) error {
	w, err := c.inner.NewWatcher(ctx, types.Watch{
		Kinds: []types.WatchKind{{Kind: types.KindAccessRequest}},
	})
	if err != nil {
		return fmt.Errorf("new watcher: %w", err)
	}
	defer w.Close()

	for {
		select {
		case <-ctx.Done():
			return nil
		case event := <-w.Events():
			if event.Type != types.OpPut {
				continue
			}
			req, ok := event.Resource.(types.AccessRequest)
			if !ok || req.GetState() != types.RequestState_PENDING {
				continue
			}
			onRequest(AccessRequest{
				ID:        req.GetName(),
				Requester: req.GetUser(),
				Roles:     req.GetRoles(),
				Reason:    req.GetRequestReason(),
			})
		case <-w.Done():
			return w.Error()
		}
	}
}

