package slack

import (
	"fmt"
	"strings"

	slackapi "github.com/slack-go/slack"
)

const (
	actionApprove  = "approve"
	actionDeny     = "deny"
	actionMoreInfo = "more_info"
	callbackBlock  = "access_request"
	callbackDeny   = "deny_modal"
	callbackInfo   = "more_info_modal"
)

func buildRequestBlocks(id, requester, reason string, roles []string) []slackapi.Block {
	if reason == "" {
		reason = "_no reason provided_"
	}
	return []slackapi.Block{
		slackapi.NewSectionBlock(
			slackapi.NewTextBlockObject("mrkdwn", ":key: *New Teleport Access Request*", false, false),
			nil, nil,
		),
		slackapi.NewSectionBlock(nil, []*slackapi.TextBlockObject{
			slackapi.NewTextBlockObject("mrkdwn", fmt.Sprintf("*Requester*\n%s", requester), false, false),
			slackapi.NewTextBlockObject("mrkdwn", fmt.Sprintf("*Roles*\n%s", formatRoles(roles)), false, false),
			slackapi.NewTextBlockObject("mrkdwn", fmt.Sprintf("*Reason*\n%s", reason), false, false),
			slackapi.NewTextBlockObject("mrkdwn", fmt.Sprintf("*Request ID*\n`%s`", id), false, false),
		}, nil),
		slackapi.NewActionBlock(
			callbackBlock,
			slackapi.NewButtonBlockElement(actionApprove, id,
				slackapi.NewTextBlockObject("plain_text", "✓ Approve", true, false),
			).WithStyle(slackapi.StylePrimary),
			slackapi.NewButtonBlockElement(actionDeny, id,
				slackapi.NewTextBlockObject("plain_text", "✗ Deny", true, false),
			).WithStyle(slackapi.StyleDanger),
			slackapi.NewButtonBlockElement(actionMoreInfo, id,
				slackapi.NewTextBlockObject("plain_text", "? Need More Info", true, false),
			),
		),
	}
}

func buildApprovedBlocks(requester, approver string, roles []string) []slackapi.Block {
	return []slackapi.Block{
		slackapi.NewSectionBlock(
			slackapi.NewTextBlockObject("mrkdwn",
				fmt.Sprintf(":white_check_mark: *Access Approved*\n*Requester:* %s  *Roles:* %s  *Approved by:* %s",
					requester, formatRoles(roles), approver),
				false, false),
			nil, nil,
		),
	}
}

func buildDeniedBlocks(requester, denier, reason string, roles []string) []slackapi.Block {
	return []slackapi.Block{
		slackapi.NewSectionBlock(
			slackapi.NewTextBlockObject("mrkdwn",
				fmt.Sprintf(":x: *Access Denied*\n*Requester:* %s  *Roles:* %s  *Denied by:* %s\n*Reason:* %s",
					requester, formatRoles(roles), denier, reason),
				false, false),
			nil, nil,
		),
	}
}

func buildMoreInfoBlocks(asker, question string) []slackapi.Block {
	return []slackapi.Block{
		slackapi.NewSectionBlock(
			slackapi.NewTextBlockObject("mrkdwn",
				fmt.Sprintf(":question: *More information requested by %s:*\n%s\n_Request is still pending._",
					asker, question),
				false, false),
			nil, nil,
		),
	}
}

func denyModal(requestID string) slackapi.ModalViewRequest {
	return slackapi.ModalViewRequest{
		Type:            slackapi.VTModal,
		CallbackID:      callbackDeny,
		PrivateMetadata: requestID,
		Title:           slackapi.NewTextBlockObject("plain_text", "Deny Access Request", false, false),
		Submit:          slackapi.NewTextBlockObject("plain_text", "Deny", false, false),
		Close:           slackapi.NewTextBlockObject("plain_text", "Cancel", false, false),
		Blocks: slackapi.Blocks{BlockSet: []slackapi.Block{
			slackapi.NewInputBlock("reason_block",
				slackapi.NewTextBlockObject("plain_text", "Reason for denial", false, false),
				nil,
				slackapi.NewPlainTextInputBlockElement(
					slackapi.NewTextBlockObject("plain_text", "Why is this request being denied?", false, false),
					"reason",
				),
			),
		}},
	}
}

func moreInfoModal(requestID string) slackapi.ModalViewRequest {
	return slackapi.ModalViewRequest{
		Type:            slackapi.VTModal,
		CallbackID:      callbackInfo,
		PrivateMetadata: requestID,
		Title:           slackapi.NewTextBlockObject("plain_text", "Request More Info", false, false),
		Submit:          slackapi.NewTextBlockObject("plain_text", "Send", false, false),
		Close:           slackapi.NewTextBlockObject("plain_text", "Cancel", false, false),
		Blocks: slackapi.Blocks{BlockSet: []slackapi.Block{
			slackapi.NewInputBlock("question_block",
				slackapi.NewTextBlockObject("plain_text", "What do you need to know?", false, false),
				nil,
				slackapi.NewPlainTextInputBlockElement(
					slackapi.NewTextBlockObject("plain_text", "e.g. Please provide a Jira ticket number for this request.", false, false),
					"question",
				),
			),
		}},
	}
}

func formatRoles(roles []string) string {
	if len(roles) == 0 {
		return "_none_"
	}
	parts := make([]string, len(roles))
	for i, r := range roles {
		parts[i] = "`" + r + "`"
	}
	return strings.Join(parts, ", ")
}

