package slack

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"net/url"

	"github.com/immuta/operations/services/beammeup/internal/config"
	"github.com/immuta/operations/services/beammeup/internal/state"
	"github.com/immuta/operations/services/beammeup/internal/teleport"
	"github.com/labstack/echo/v4"
	slackapi "github.com/slack-go/slack"
)

type Handler struct {
	cfg      *config.Config
	slack    *slackapi.Client
	teleport *teleport.Client
	store    *state.Store
}

func NewHandler(cfg *config.Config, slackClient *slackapi.Client, tpClient *teleport.Client, store *state.Store) *Handler {
	return &Handler{cfg: cfg, slack: slackClient, teleport: tpClient, store: store}
}

func (h *Handler) Register(e *echo.Echo) {
	e.POST("/slack/interactive", h.interactive)
}

func (h *Handler) PostAccessRequest(req teleport.AccessRequest) error {
	blocks := buildRequestBlocks(req.ID, req.Requester, req.Reason, req.Roles)
	_, ts, err := h.slack.PostMessage(h.cfg.SlackChannel, slackapi.MsgOptionBlocks(blocks...))
	if err != nil {
		return fmt.Errorf("post message: %w", err)
	}
	h.store.Set(&state.Entry{
		TeleportRequestID: req.ID,
		SlackChannel:      h.cfg.SlackChannel,
		SlackMessageTS:    ts,
		Requester:         req.Requester,
		Roles:             req.Roles,
		Reason:            req.Reason,
	})
	return nil
}

func (h *Handler) interactive(c echo.Context) error {
	r := c.Request()

	sv, err := slackapi.NewSecretsVerifier(r.Header, h.cfg.SlackSigningSecret)
	if err != nil {
		return c.NoContent(http.StatusUnauthorized)
	}
	body, err := io.ReadAll(io.TeeReader(r.Body, &sv))
	if err != nil {
		return c.NoContent(http.StatusBadRequest)
	}
	if err = sv.Ensure(); err != nil {
		slog.Warn("slack signature verification failed", "error", err)
		return c.NoContent(http.StatusUnauthorized)
	}

	vals, err := url.ParseQuery(string(body))
	if err != nil {
		return c.NoContent(http.StatusBadRequest)
	}

	var payload slackapi.InteractionCallback
	if err = json.Unmarshal([]byte(vals.Get("payload")), &payload); err != nil {
		return c.NoContent(http.StatusBadRequest)
	}

	switch payload.Type {
	case slackapi.InteractionTypeBlockActions:
		return h.handleBlockAction(c, payload)
	case slackapi.InteractionTypeViewSubmission:
		return h.handleModalSubmission(c, payload)
	}
	return c.NoContent(http.StatusOK)
}

func (h *Handler) handleBlockAction(c echo.Context, p slackapi.InteractionCallback) error {
	if len(p.ActionCallback.BlockActions) == 0 {
		return c.NoContent(http.StatusOK)
	}
	action := p.ActionCallback.BlockActions[0]
	actor := p.User.Name

	switch action.ActionID {
	case actionApprove:
		entry, ok := h.store.Get(action.Value)
		if !ok {
			return c.NoContent(http.StatusOK) // already handled
		}
		// Respond to Slack immediately; Teleport call happens async.
		go h.doApprove(entry, actor)

	case actionDeny:
		// TriggerID expires in 3s — open the modal before responding.
		if _, err := h.slack.OpenView(p.TriggerID, denyModal(action.Value)); err != nil {
			slog.Error("open deny modal", "error", err)
			return c.NoContent(http.StatusInternalServerError)
		}

	case actionMoreInfo:
		if _, err := h.slack.OpenView(p.TriggerID, moreInfoModal(action.Value)); err != nil {
			slog.Error("open more_info modal", "error", err)
			return c.NoContent(http.StatusInternalServerError)
		}
	}
	return c.NoContent(http.StatusOK)
}

func (h *Handler) handleModalSubmission(c echo.Context, p slackapi.InteractionCallback) error {
	requestID := p.View.PrivateMetadata
	actor := p.User.Name

	switch p.View.CallbackID {
	case callbackDeny:
		reason := p.View.State.Values["reason_block"]["reason"].Value
		entry, ok := h.store.Get(requestID)
		if !ok {
			return c.NoContent(http.StatusOK)
		}
		go h.doDeny(entry, actor, reason)

	case callbackInfo:
		question := p.View.State.Values["question_block"]["question"].Value
		entry, ok := h.store.Get(requestID)
		if !ok {
			return c.NoContent(http.StatusOK)
		}
		go h.doMoreInfo(entry, actor, question)
	}
	return c.NoContent(http.StatusOK)
}

func (h *Handler) doApprove(entry *state.Entry, actor string) {
	if err := h.teleport.Approve(context.Background(), entry.TeleportRequestID, actor); err != nil {
		slog.Error("approve failed", "error", err, "id", entry.TeleportRequestID)
		return
	}
	h.updateMessage(entry, buildApprovedBlocks(entry.Requester, actor, entry.Roles))
	h.store.Delete(entry.TeleportRequestID)
}

func (h *Handler) doDeny(entry *state.Entry, actor, reason string) {
	if err := h.teleport.Deny(context.Background(), entry.TeleportRequestID, reason, actor); err != nil {
		slog.Error("deny failed", "error", err, "id", entry.TeleportRequestID)
		return
	}
	h.updateMessage(entry, buildDeniedBlocks(entry.Requester, actor, reason, entry.Roles))
	h.store.Delete(entry.TeleportRequestID)
}

func (h *Handler) doMoreInfo(entry *state.Entry, actor, question string) {
	blocks := buildMoreInfoBlocks(actor, question)
	// Post as a thread reply so the original message (with buttons) stays actionable.
	if _, _, err := h.slack.PostMessage(
		entry.SlackChannel,
		slackapi.MsgOptionBlocks(blocks...),
		slackapi.MsgOptionTS(entry.SlackMessageTS),
	); err != nil {
		slog.Error("post more_info thread", "error", err, "id", entry.TeleportRequestID)
	}
}

func (h *Handler) updateMessage(entry *state.Entry, blocks []slackapi.Block) {
	if _, _, _, err := h.slack.UpdateMessage(
		entry.SlackChannel,
		entry.SlackMessageTS,
		slackapi.MsgOptionBlocks(blocks...),
	); err != nil {
		slog.Error("update message failed", "error", err, "id", entry.TeleportRequestID)
	}
}

